contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 unlockTime) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        (uint256 beforeUnlock, uint256 beforeBalance) = c.Acc(address(this));
        uint256 beforeMinSum = c.MinSum();
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterUnlock, uint256 afterBalance) = c.Acc(address(this));
        uint256 afterMinSum = c.MinSum();
        uint256 afterContractBalance = address(c).balance;

        assert(
            !reverted &&
            afterBalance == beforeBalance + amount &&
            afterMinSum == beforeMinSum &&
            afterContractBalance == beforeContractBalance + amount &&
            afterUnlock == (unlockTime > block.timestamp ? unlockTime : block.timestamp)
        );
    }

    receive() external payable {}
}

