contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Seed the caller's balance through the public entry point so the caller
        // is known and any unlock time is set. Use a sentinel unlockTime that is
        // certainly in the past when 0, else map it to a relative future value.
        uint effectiveUnlock = unlockTime == 0 ? 0 : block.timestamp + unlockTime;
        c.Put{value: depositAmount}(effectiveUnlock);

        // Read observable before-state.
        (, uint balanceBefore) = c.Acc(address(this));
        uint unlockBefore;
        (unlockBefore, ) = c.Acc(address(this));
        uint minSum = c.MinSum();
        uint nowTime = block.timestamp;

        bool shouldSucceed = (balanceBefore >= minSum)
            && (balanceBefore >= collectAmount)
            && (nowTime > unlockBefore);

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint balanceAfter) = c.Acc(address(this));

        if (shouldSucceed) {
            assert(!reverted
                && balanceAfter == balanceBefore - collectAmount
                && address(c).balance >= 0);
        } else {
            assert(reverted && balanceAfter == balanceBefore);
        }
    }

    receive() external payable {}
}

